/// A dependency-free browser player served by the same native server runtime.
/// Authentication uses an HttpOnly, SameSite=Strict cookie, including range reads.
const webPlayerHtml = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Tangerine</title><style>
:root{color-scheme:dark;--canvas:#191919;--panel:#222120;--raised:#292827;--text:#f0ece8;--muted:#b3aba5;--line:#403c38;--accent:#d37918}
*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--text);font:15px system-ui,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer;background:var(--raised);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:10px 16px}button:hover,button:focus-visible{border-color:var(--accent)}button.primary{background:var(--accent);color:#381a04;border:0;font-weight:600}input,select,textarea{background:#0e0e0e;color:var(--text);border:1px solid var(--line);border-radius:6px;padding:12px;max-width:100%}input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent)}header{padding:18px 24px;border-bottom:1px solid var(--line);display:flex;gap:12px;align-items:center;background:var(--panel)}.logo{color:var(--accent);font-size:28px}h1{font-size:22px;margin:0}h2{font-size:28px;margin:0 0 12px}p{color:var(--muted);line-height:1.6}.spacer{flex:1}main{max-width:1440px;margin:auto;padding:28px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:24px}.pair{max-width:540px;margin:50px auto}label{display:grid;gap:8px;margin:16px 0}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.toolbar input{flex:1;min-width:180px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:18px}.card{text-align:left;padding:0;overflow:hidden;background:var(--panel);min-width:0}.art{aspect-ratio:16/9;background:var(--raised);display:grid;place-items:center;font-size:40px;color:var(--accent)}.card strong,.card small{display:block;margin:12px;overflow-wrap:anywhere}.card small{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:1px}.status{min-height:24px;color:var(--accent);overflow-wrap:anywhere}.hidden,[hidden]{display:none!important}dialog{background:var(--canvas);color:var(--text);border:1px solid var(--line);border-radius:10px;width:min(1100px,96vw);max-height:94dvh;padding:18px}dialog::backdrop{background:#000c}.player-head{display:flex;align-items:center;gap:12px;margin-bottom:16px}.player-head strong{flex:1;overflow-wrap:anywhere}video,audio{width:100%;max-height:60dvh;background:#0e0e0e}iframe{width:100%;height:60dvh;background:white;border:0}#picture{max-width:100%;max-height:60dvh;display:block;margin:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:55dvh;overflow:auto}.study{margin-top:18px;border-top:1px solid var(--line);padding-top:16px}.study textarea{width:100%;min-height:70px}.note{padding:12px 0;border-bottom:1px solid var(--line);white-space:pre-wrap;overflow-wrap:anywhere}.muted{color:var(--muted)}@media(max-width:600px){main{padding:16px}.pair{margin:16px auto}.panel{padding:18px}header{padding:14px 16px}.grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}dialog{padding:12px}.toolbar{gap:8px}}
</style></head><body>
<header><span class="logo" aria-hidden="true">▶</span><h1>Tangerine</h1><span id="serverName" class="muted"></span><span class="spacer"></span><button id="disconnect" hidden>Disconnect</button></header>
<main><section id="pair" class="panel pair"><h2>Your media, everywhere.</h2><p>Pair this browser with your Tangerine server to watch, listen, read, and keep your study notes together.</p>
<form id="pairForm"><label>This player’s name<input id="deviceName" maxlength="80" value="Browser player" required autocomplete="off"></label><label>Pairing code<input id="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code" placeholder="Six digits from the Server screen"></label><button class="primary" id="pairButton">Pair this player</button></form><p>Use a trusted private network. HTTP traffic is authenticated but unencrypted.</p></section>
<section id="hostRemote" class="panel" hidden><h3>Control host player</h3><p id="hostNow">No player open</p><div class="toolbar"><button id="hostPrevious">Previous</button><button id="hostPlay">Play</button><button id="hostPause">Pause</button><button id="hostBack">Back 10s</button><button id="hostForward">Forward 10s</button><button id="hostNext">Next</button></div><p id="hostStatus" class="status" role="status"></p></section><section id="library" hidden><h2>Your library</h2><p>Video, music, documents, and learning. Streamed from your own server.</p><div class="toolbar"><select id="category" aria-label="Media category"><option value="all">All media</option><option value="video">Videos</option><option value="audio">Music</option><option value="documents">Documents</option></select><select id="collection" aria-label="Library"><option value="all">All libraries</option></select><input id="search" type="search" placeholder="Search your media" aria-label="Search media"><button id="refresh">Refresh</button></div><div id="items" class="grid"></div><p id="count" class="muted"></p></section><p id="status" class="status" role="status" aria-live="polite"></p></main>
<dialog id="player"><div class="player-head"><strong id="mediaTitle"></strong><button id="closePlayer" aria-label="Close player">Close</button></div><video id="video" controls playsinline hidden></video><audio id="audio" controls hidden></audio><iframe id="document" title="Document preview" hidden></iframe><img id="picture" alt="Selected media" hidden><pre id="text" hidden></pre><p id="unsupported" hidden>This resource needs a compatible native app. Browser playback depends on the browser’s supported formats.</p><p id="playerStatus" role="status" class="status"></p><a id="openPdf" target="_blank" rel="noopener" hidden>Open PDF separately</a><div class="toolbar"><label>Playback speed<select id="speed"><option>0.25</option><option>0.5</option><option>0.75</option><option selected>1</option><option>1.25</option><option>1.5</option><option>2</option><option>3</option><option>4</option></select></label><button id="bookmark">Bookmark position</button></div><section class="study"><h3>Study</h3><label>Note<textarea id="noteInput" maxlength="100000" placeholder="Capture an idea or a timestamped note"></textarea></label><button id="saveNote" class="primary">Save note</button><div id="notes"></div></section></dialog>
<script>
'use strict';
const $=id=>document.getElementById(id);
let snapshot=null,deviceId=null,current=null,media=null,lastSave=0,saveChain=Promise.resolve(),textRequest=0;
const request=async(path,body)=>{const response=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(!response.ok){if(response.status===401||response.status===403){$('pair').hidden=false;$('library').hidden=true;$('disconnect').hidden=true;}throw new Error(response.status===401||response.status===403?'Pairing is required or access was revoked. Check the current server code.':'The server could not complete this request.');}return response.json();};
const status=message=>$('status').textContent=message;
const title=item=>item.userTitle||item.title||item.filename;
const id=()=>`web-${Date.now()}-${Math.random().toString(36).slice(2)}`;
async function load(){const session=await request('/v1/session');deviceId=session.deviceId;snapshot=await request('/v1/snapshot');$('pair').hidden=true;$('library').hidden=false;$('disconnect').hidden=false;$('serverName').textContent=session.name;const selected=$('collection').value;$('collection').replaceChildren(new Option('All libraries','all'));for(const library of snapshot.libraries)$('collection').add(new Option(library.title,library.id));if([...$('collection').options].some(option=>option.value===selected))$('collection').value=selected;render();await loadHostRemote();}
function render(){const query=$('search').value.toLowerCase(),kind=$('category').value,library=$('collection').value;const items=snapshot.items.filter(item=>!item.unavailable&&(library==='all'||item.libraryId===library)&&(kind==='all'||(kind==='documents'?!['video','audio'].includes(item.itemType):item.itemType===kind))&&title(item).toLowerCase().includes(query));$('items').replaceChildren();for(const item of items.slice(0,240)){const card=document.createElement('button');card.className='card';const art=document.createElement('div');art.className='art';art.textContent=item.itemType==='audio'?'♫':item.itemType==='video'?'▶':'▤';const name=document.createElement('strong');name.textContent=title(item);const type=document.createElement('small');type.textContent=`${item.itemType} · Server`;card.append(art,name,type);card.onclick=()=>openItem(item).catch(error=>status(error.message));$('items').append(card);}$('count').textContent=items.length>240?`Showing 240 of ${items.length} items. Search to narrow your library.`:`${items.length} items`;}
function enqueue(body){const task=saveChain.catch(()=>{}).then(()=>request('/v1/snapshot',{schemaVersion:snapshot.schemaVersion,...body}));saveChain=task;return task;}
function saveProgress(ended=false){if(!media||!current||!Number.isFinite(media.duration)||media.duration<=0)return Promise.resolve();const item=current,position=media.currentTime,duration=media.duration,speed=media.playbackRate;let previous=(snapshot.playback||[]).find(row=>row.itemId===item.id);const completed=previous?.manualCompletion??(previous?.completed||ended||position/duration>=0.9),now=Date.now();const row={itemId:item.id,lastPositionSeconds:position,resumePositionSeconds:completed?0:Math.max(0,position-10),durationSeconds:duration,percentWatched:completed?100:Math.max(previous?.percentWatched||0,position/duration*100),completed,manualCompletion:previous?.manualCompletion??null,playbackSpeed:speed,lastOpenedAt:now,lastEventAt:now,deviceId,version:(previous?.version||0)+1};snapshot.playback=(snapshot.playback||[]).filter(value=>value.itemId!==item.id);snapshot.playback.push(row);return enqueue({playback:[row]}).catch(error=>{$('playerStatus').textContent='Progress could not be saved. Keep this player open and retry when the server is available.';throw error;});}
async function closeMedia(){++textRequest;if(media){media.pause();await saveProgress().catch(()=>{});media.removeAttribute('src');media.load();}media=null;current=null;$('document').removeAttribute('src');$('picture').removeAttribute('src');$('text').textContent='';}
async function openItem(item){await closeMedia();current=item;$('mediaTitle').textContent=title(item);$('openPdf').hidden=true;$('playerStatus').textContent='';$('noteInput').value='';for(const key of ['video','audio','document','picture','text','unsupported'])$(key).hidden=true;const source=`/v1/media/${encodeURIComponent(item.id)}`;if(['video','audio'].includes(item.itemType)){media=$(item.itemType);media.hidden=false;const progress=(snapshot.playback||[]).find(row=>row.itemId===item.id);media.onloadedmetadata=()=>{media.playbackRate=progress?.playbackSpeed||1;$('speed').value=String(media.playbackRate);if(progress&&!progress.completed){media.currentTime=Math.min(Math.max(0,progress.lastPositionSeconds-10),Math.max(0,media.duration-0.1));}};media.onerror=()=>{$('playerStatus').textContent='This browser could not play this file. Try a supported format or use a native Tangerine player.';};media.src=source;media.load();}else if(item.itemType==='pdf'){$('document').hidden=false;$('document').src=source;$('openPdf').hidden=false;$('openPdf').href=source;$('playerStatus').textContent='If this browser cannot display the PDF preview, open it separately or use a native Tangerine player.';}else if(item.itemType==='image'){$('picture').hidden=false;$('picture').src=source;}else if(['txt','html'].includes(item.itemType)){const generation=++textRequest;$('text').hidden=false;const response=await fetch(source,{credentials:'same-origin'});if(!response.ok)throw new Error('The document could not be loaded.');const reader=response.body.getReader();let chunks=[],size=0;while(true){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>2*1024*1024){await reader.cancel();throw new Error('Open this large text document in a native player.');}chunks.push(part.value);}if(generation!==textRequest)return;const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}$('text').textContent=new TextDecoder().decode(bytes);}else{$('unsupported').hidden=false;}renderNotes();$('bookmark').disabled=!media;$('speed').disabled=!media;if(!$('player').open)$('player').showModal();}
function renderNotes(){$('notes').replaceChildren();for(const note of (snapshot.notes||[]).filter(note=>note.itemId===current?.id&&!note.deleted)){const entry=document.createElement('div');entry.className='note';entry.textContent=(note.positionSeconds==null?'':`[${Math.floor(note.positionSeconds/60)}:${String(Math.floor(note.positionSeconds%60)).padStart(2,'0')}] `)+note.content;$('notes').append(entry);}}
for(const kind of ['video','audio']){const element=$(kind);element.ontimeupdate=()=>{if(element===media&&Date.now()-lastSave>5000){lastSave=Date.now();saveProgress().catch(()=>{});}};element.onpause=()=>{if(element===media)saveProgress().catch(()=>{});};element.onended=()=>{if(element===media)saveProgress(true).catch(()=>{});};}
$('speed').onchange=()=>{if(media)media.playbackRate=Number($('speed').value);};
$('closePlayer').onclick=async()=>{await closeMedia();$('player').close();};$('player').addEventListener('cancel',event=>{event.preventDefault();$('closePlayer').click();});
$('saveNote').onclick=async()=>{if(!current||!$('noteInput').value.trim())return;const item=current,now=Date.now(),note={id:id(),libraryId:item.libraryId,itemId:item.id,content:$('noteInput').value.trim(),positionSeconds:media?.currentTime??null,pageNumber:null,createdAt:now,updatedAt:now,deviceId,version:1,deleted:false};$('saveNote').disabled=true;try{await enqueue({notes:[note]});snapshot.notes=snapshot.notes||[];snapshot.notes.push(note);if(current===item){$('noteInput').value='';renderNotes();$('playerStatus').textContent='Note saved.';}}catch(error){$('playerStatus').textContent=error.message;}finally{$('saveNote').disabled=false;}};
$('bookmark').onclick=async()=>{if(!current||!media)return;const now=Date.now(),position=media.currentTime,bookmark={id:id(),libraryId:current.libraryId,itemId:current.id,title:`${title(current)} · ${Math.floor(position/60)}:${String(Math.floor(position%60)).padStart(2,'0')}`,description:null,positionSeconds:position,pageNumber:null,createdAt:now,updatedAt:now,deviceId,version:1,deleted:false};try{await enqueue({bookmarks:[bookmark]});$('playerStatus').textContent='Bookmark saved.';}catch(error){$('playerStatus').textContent=error.message;}};
$('pairForm').onsubmit=async event=>{event.preventDefault();$('pairButton').disabled=true;try{await request('/v1/pair',{name:$('deviceName').value.trim(),code:$('code').value});$('code').value='';await load();status('Connected to your media server.');}catch(error){status(error.message);}finally{$('pairButton').disabled=false;}};
$('disconnect').onclick=async()=>{await closeMedia();if($('player').open)$('player').close();try{await request('/v1/logout',{});}catch(error){status(error.message);}snapshot=null;$('pair').hidden=false;$('library').hidden=true;$('disconnect').hidden=true;$('serverName').textContent='';status('Disconnected. Pair again to reconnect.');};
$('refresh').onclick=()=>load().then(()=>status('Library refreshed.')).catch(error=>status(error.message));for(const key of ['category','collection','search'])$(key).addEventListener('input',()=>{if(snapshot)render();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveProgress().catch(()=>{});});
let hostPosition=0,hostDuration=0;
async function loadHostRemote(){if($('library').hidden||document.hidden)return;const host=await request('/v1/playback');$('hostRemote').hidden=!host.enabled;if(host.enabled){hostPosition=Number(host.position)||0;hostDuration=Number(host.duration)||0;$('hostNow').textContent=host.active?`${host.title} · ${host.playing?'Playing':'Paused'} · ${Math.floor(hostPosition)} / ${Math.floor(hostDuration)}s`:'Open a player on the host to control it.';}}
async function hostAction(action,value){try{await request('/v1/playback',{action,...(value===undefined?{}:{value})});$('hostStatus').textContent='';await loadHostRemote();}catch(error){$('hostStatus').textContent=error.message;}}
$('hostPrevious').onclick=()=>hostAction('previous');$('hostNext').onclick=()=>hostAction('next');$('hostPlay').onclick=()=>hostAction('play');$('hostPause').onclick=()=>hostAction('pause');$('hostBack').onclick=()=>hostAction('seek',Math.max(0,hostPosition-10));$('hostForward').onclick=()=>hostAction('seek',Math.min(hostDuration,hostPosition+10));
setInterval(()=>loadHostRemote().catch(()=>{}),2000);
load().catch(()=>status('Enter the code shown on your server to connect.'));
</script></body></html>''';
